"""أدوات الأعمال: محاسبة ومالية، تسويق، تجارة إلكترونية (مبتكرة)، إدارة، موارد بشرية."""
def F(id, l, t='n', v='', **k):
    d = dict(id=id, l=l, t=t, v=v); d.update(k); return d
def S(id, l, opts, v=None):
    return dict(id=id, l=l, t='select', o=opts, v=opts[0][0] if v is None else v)
T = []
def add(slug, cat, icon, title, desc, fields, js, ai=False):
    T.append(dict(slug=slug, cat=cat, icon=icon, title=title, desc=desc, fields=fields, js=js, ai=ai))

CATS = {
 'finance': ('💰', 'المحاسبة والمالية', 'حاسبات وقوائم مالية وأدوات تجهيز برومت للمحاسب.'),
 'marketing': ('📣', 'التسويق', 'ميزانيات وتقويم محتوى ونصوص إعلانية وروابط تتبع وتحليل.'),
 'ecom': ('🛒', 'ابتكارات التجارة الإلكترونية', 'أدوات مبتكرة: التخطيط العكسي للأرباح، محاكي السيناريوهات، اختبار A/B وغيرها.'),
 'management': ('🧭', 'الإدارة', 'أهداف OKR وSWOT وأولويات وخطط مشاريع واجتماعات وقرارات.'),
 'hr': ('👥', 'الموارد البشرية', 'وصف وظيفي ومقابلات ونهاية خدمة ورواتب وإجازات وتهيئة موظفين.'),
}
PRM = "ai"

# ============ FINANCE ============
add('vat-calculator', 'finance', '🧾', 'حاسبة ضريبة القيمة المضافة', 'أضف الضريبة إلى المبلغ أو استخرجها منه بسرعة.',
 [F('a', 'المبلغ', 'n', 1000), F('r', 'نسبة الضريبة %', 'n', 15), S('m', 'الحالة', [('add', 'المبلغ قبل الضريبة (أضف الضريبة)'), ('ext', 'المبلغ شامل الضريبة (استخرجها)')])],
 r'''function compute(v){const r=v.r/100;let net,vat,tot;if(v.m==='add'){net=v.a;vat=net*r;tot=net+vat}else{tot=v.a;net=tot/(1+r);vat=tot-net}
return kpis([kpi('قبل الضريبة',f(net)),kpi('الضريبة',f(vat),'bad'),kpi('الإجمالي',f(tot),'good')])+note('النسبة تُعدّل حسب نظام بلدك. راجع الجهة الضريبية الرسمية.')}''')

add('loan-installment', 'finance', '🏦', 'حاسبة القسط والتمويل', 'القسط الشهري وإجمالي الفوائد وجدول السداد.',
 [F('p', 'مبلغ التمويل', 'n', 100000), F('r', 'النسبة السنوية %', 'n', 6), F('n', 'المدة بالأشهر', 'n', 36)],
 r'''function compute(v){const n=Math.max(1,Math.round(v.n)),i=v.r/1200;const pmt=i?v.p*i/(1-Math.pow(1+i,-n)):v.p/n;let bal=v.p,rows=[];
for(let k=1;k<=Math.min(n,12);k++){const it=bal*i,pr=pmt-it;bal-=pr;rows.push([k,f(pmt),f(it),f(pr),f(Math.max(bal,0))])}
return kpis([kpi('القسط الشهري',f(pmt),'good'),kpi('إجمالي المدفوع',f(pmt*n)),kpi('إجمالي الفوائد',f(pmt*n-v.p),'bad')])+'<h3>أول 12 شهرًا</h3>'+tbl(['الشهر','القسط','فائدة','أصل','المتبقي'],rows)+note('حساب بفائدة متناقصة تقديري. شروط البنك الفعلية قد تختلف (رسوم، فائدة ثابتة).')}''')

add('break-even', 'finance', '⚖️', 'حاسبة نقطة التعادل', 'كم وحدة تبيع لتغطي تكاليفك؟',
 [F('fx', 'التكاليف الثابتة الشهرية', 'n', 8000), F('pr', 'سعر بيع الوحدة', 'n', 100), F('vc', 'التكلفة المتغيرة للوحدة', 'n', 60), F('ex', 'المبيعات المتوقعة (وحدات/شهر)', 'n', 300)],
 r'''function compute(v){const cm=v.pr-v.vc;if(cm<=0)return'<b>التكلفة المتغيرة تساوي السعر أو تزيد: لا يمكن التعادل.</b>';const u=v.fx/cm,rev=u*v.pr;const prof=(v.ex*cm)-v.fx;const ms=v.ex>0?(v.ex-u)/v.ex*100:0;
return kpis([kpi('وحدات التعادل',f(Math.ceil(u),0),'good'),kpi('إيراد التعادل',f(rev)),kpi('هامش المساهمة',f(cm/v.pr*100,1)+'%'),kpi('الربح المتوقع',f(prof),prof<0?'bad':'good'),kpi('هامش الأمان',f(ms,1)+'%')])+note('هامش الأمان = المسافة بين مبيعاتك المتوقعة ونقطة التعادل.')}''')

add('income-statement', 'finance', '📊', 'قائمة الدخل المبسطة', 'أدخل الإيرادات والتكاليف والمصروفات بسطر لكل بند واحصل على الأرباح والنسب.',
 [F('rv', 'الإيرادات (بند | مبلغ)', 'textarea', 'مبيعات المنتجات | 120000\nخدمات | 15000', r=4), F('cg', 'تكلفة المبيعات (بند | مبلغ)', 'textarea', 'مشتريات | 60000\nشحن وتغليف | 8000', r=4), F('ox', 'المصروفات التشغيلية (بند | مبلغ)', 'textarea', 'رواتب | 25000\nإيجار | 6000\nإعلانات | 12000', r=4)],
 r'''function compute(v){const sm=t=>lines(t).reduce((a,r)=>a+num(r[1]||0),0);const R=sm(v.rv),C=sm(v.cg),X=sm(v.ox);const G=R-C,N=G-X;const p=x=>R?f(x/R*100,1)+'%':'-';
const rows=[['الإيرادات',f(R),'100%'],['تكلفة المبيعات',f(C),p(C)],['<b>مجمل الربح</b>','<b>'+f(G)+'</b>',p(G)],['المصروفات التشغيلية',f(X),p(X)],['<b>صافي الربح</b>','<b>'+f(N)+'</b>',p(N)]];
return kpis([kpi('مجمل الربح',f(G),G<0?'bad':'good'),kpi('صافي الربح',f(N),N<0?'bad':'good'),kpi('هامش صافٍ',p(N))])+tbl(['البند','المبلغ','% من الإيراد'],rows)+note('قائمة إدارية مبسطة وليست قوائم مالية معتمدة (ضرائب/استهلاك/زكاة غير محسوبة).')}''')

add('cash-flow-forecast', 'finance', '💧', 'توقع التدفق النقدي', 'ستة أشهر قادمة: متى ينفد النقد؟',
 [F('op', 'الرصيد النقدي الحالي', 'n', 30000), F('sl', 'مبيعات الشهر الأول', 'n', 50000), F('gr', 'نمو شهري متوقع %', 'n', 5), F('vp', 'تكاليف متغيرة % من المبيعات', 'n', 55), F('fx', 'مصروفات ثابتة شهرية', 'n', 15000), F('dl', 'تأخر التحصيل (أشهر)', 'n', 0)],
 r'''function compute(v){let bal=v.op,rows=[],minb=bal,low='';const d=Math.round(v.dl);const sales=[];for(let i=0;i<6;i++)sales.push(v.sl*Math.pow(1+v.gr/100,i));
for(let i=0;i<6;i++){const inflow=i-d>=0?sales[i-d]:0;const out=sales[i]*v.vp/100+v.fx;bal+=inflow-out;if(bal<minb){minb=bal}if(bal<0&&!low)low='الشهر '+(i+1);rows.push([i+1,f(inflow),f(out),'<b'+(bal<0?' style="color:#c2410c"':'')+'>'+f(bal)+'</b>'])}
return kpis([kpi('أدنى رصيد',f(minb),minb<0?'bad':'good'),kpi('أول شهر عجز',low||'لا يوجد',low?'bad':'good')])+tbl(['الشهر','التدفق الداخل','التدفق الخارج','الرصيد'],rows)+note(low?'⚠️ يحدث عجز نقدي: قلّل المصروفات أو سرّع التحصيل أو وفّر تمويلًا مسبقًا.':'التوقع افتراضي. حدّثه بأرقامك الفعلية شهريًا.')}''')

add('invoice-generator', 'finance', '🧮', 'مولّد فاتورة / عرض سعر', 'أنشئ فاتورة أو عرض سعر قابل للطباعة بصيغة PDF.',
 [F('no', 'رقم المستند', 't', 'INV-001'), F('dt', 'التاريخ', 'date', ''), F('se', 'اسم البائع', 't', 'متجري'), F('vt', 'الرقم الضريبي (اختياري)', 't', ''), F('by', 'اسم العميل', 't', 'العميل'), F('vr', 'نسبة الضريبة %', 'n', 15),
  F('it', 'البنود (وصف | كمية | سعر الوحدة)', 'textarea', 'منتج أ | 2 | 150\nشحن | 1 | 25', r=5)],
 r'''function compute(v){let sub=0;const rows=lines(v.it).map((r,i)=>{const q=num(r[1]||1),p=num(r[2]||0),t=q*p;sub+=t;return[i+1,esc(r[0]||''),f(q,0),f(p),f(t)]});const vat=sub*v.vr/100;
return '<div style="background:#fff;padding:18px;border:1px solid #e6e0f5;border-radius:14px"><h2>فاتورة / عرض سعر</h2><p>رقم: <b>'+esc(v.no)+'</b> — التاريخ: '+esc(v.dt||new Date().toISOString().slice(0,10))+'</p><p>البائع: <b>'+esc(v.se)+'</b>'+(v.vt?' — الرقم الضريبي: '+esc(v.vt):'')+'</p><p>العميل: <b>'+esc(v.by)+'</b></p>'+tbl(['#','الوصف','الكمية','السعر','الإجمالي'],rows)+'<p>المجموع: <b>'+f(sub)+'</b></p><p>الضريبة ('+f(v.vr,0)+'%): <b>'+f(vat)+'</b></p><h3>الإجمالي: '+f(sub+vat)+'</h3></div>'+note('هذا المستند للتوضيح وعروض الأسعار. الفواتير الضريبية الرسمية تتطلب حلًّا معتمدًا لدى الجهة الضريبية في بلدك.')}''')

add('financial-ratios', 'finance', '📐', 'النسب المالية وتفسيرها', 'السيولة والرافعة والربحية مع تفسير مبسط.',
 [F('ca', 'الأصول المتداولة', 'n', 150000), F('cl', 'الالتزامات المتداولة', 'n', 90000), F('inv', 'المخزون', 'n', 50000), F('ta', 'إجمالي الأصول', 'n', 400000), F('tl', 'إجمالي الالتزامات', 'n', 180000), F('rv', 'الإيرادات', 'n', 600000), F('ni', 'صافي الربح', 'n', 60000)],
 r'''function compute(v){const eq=v.ta-v.tl;const cr=v.cl?v.ca/v.cl:0,qr=v.cl?(v.ca-v.inv)/v.cl:0,de=eq?v.tl/eq:0,roa=v.ta?v.ni/v.ta*100:0,roe=eq?v.ni/eq*100:0,nm=v.rv?v.ni/v.rv*100:0;
const hint=(x,a,b,t1,t2,t3)=>x<a?t1:(x<b?t2:t3);
return tbl(['النسبة','القيمة','تفسير مبسط'],[['السيولة الجارية',f(cr),hint(cr,1,2,'⚠️ أقل من 1: قد يصعب سداد الالتزامات القريبة','مقبولة','قوية (لا تُترك السيولة خاملة)')],['السيولة السريعة',f(qr),hint(qr,0.8,1.5,'ضعيفة','مقبولة','جيدة')],['الدين إلى حقوق الملكية',f(de),hint(de,1,2,'رافعة منخفضة','رافعة متوسطة','⚠️ رافعة مرتفعة')],['العائد على الأصول %',f(roa,1),'كلما ارتفع كان استخدام الأصول أفضل'],['العائد على الملكية %',f(roe,1),'يقيس ربح المساهمين'],['هامش صافي %',f(nm,1),'قارنه بمتوسط قطاعك']])+note('المعايير تختلف بين القطاعات. هذه قراءة أولية وليست استشارة مالية.')}''')

add('zakat-estimator', 'finance', '🕌', 'مقدّر زكاة عروض التجارة', 'تقدير مبسط لوعاء زكاة النشاط بنسبة 2.5%.',
 [F('c', 'النقد والأرصدة', 'n', 40000), F('i', 'المخزون (بقيمة السوق)', 'n', 60000), F('r', 'ديون مرجوة التحصيل', 'n', 20000), F('o', 'عروض تجارة أخرى', 'n', 0), F('l', 'التزامات حالّة قريبة', 'n', 30000), F('n', 'قيمة النصاب بالعملة (تحدّثها بنفسك)', 'n', 20000, h='مثال: قيمة 85 جرام ذهب اليوم')],
 r'''function compute(v){const b=Math.max(0,v.c+v.i+v.r+v.o-v.l);const z=b>=v.n&&v.n>0?b*0.025:0;
return kpis([kpi('وعاء الزكاة التقديري',f(b)),kpi('النصاب',f(v.n)),kpi('الزكاة التقديرية (2.5%)',f(z),z?'good':'')])+note('تقدير مبسط للتعلّم. حساب الزكاة الفعلية للمنشآت يخضع لأنظمة وتفاصيل (حول الحول، بنود الوعاء) راجع الجهة المختصة أو مختصًا شرعيًا ومحاسبيًا.')}''')

add('finance-ai-prompts', 'finance', '🤖', 'مجهّز برومت المحاسب بالذكاء الاصطناعي', 'جهّز طلبًا جاهزًا لـClaude أو ChatGPT لمهام المحاسبة والتحليل المالي.',
 [S('t', 'المهمة', [('an', 'تحليل قائمة دخل'), ('va', 'تفسير انحراف الميزانية'), ('rc', 'مراجعة تسوية بنكية'), ('je', 'اقتراح قيود يومية لعملية'), ('pl', 'سياسة مصروفات للشركة'), ('ex', 'شرح تقرير مالي لغير المحاسبين')]), F('b', 'نوع النشاط', 't', 'متجر إلكتروني'), F('d', 'البيانات أو الوصف (بلا أسماء حساسة)', 'textarea', '', r=6, h='ألصق أرقامك هنا')],
 r'''function compute(v){const T={an:'حلّل قائمة الدخل التالية: اذكر 5 ملاحظات مهمة، أبرز البنود التي ارتفعت أو انخفضت بشكل غير طبيعي، واقترح 3 إجراءات لتحسين الربحية.',va:'فسّر انحراف الميزانية الفعلية عن المخططة: رتّب الأسباب المحتملة، وما الأسئلة التي يجب أن أطرحها على كل قسم، وما الإجراء التصحيحي.',rc:'ساعدني في مراجعة التسوية البنكية: صنّف الفروق (عمليات غير مسجلة، شيكات معلقة، أخطاء)، واقترح قيود التسوية اللازمة.',je:'اقترح القيود اليومية المحاسبية المناسبة للعملية الموصوفة (مدين/دائن) مع شرح مبسط لسبب كل طرف، ونبّهني لأي معالجة ضريبية يجب أن أراجعها مع مختص.',pl:'اكتب سياسة مصروفات واضحة للشركة: الأنواع المسموحة، حدود الموافقة، المستندات المطلوبة، مواعيد الصرف، وإجراءات المخالفة. في صفحة واحدة.',ex:'اشرح التقرير المالي التالي لشخص غير محاسب في فقرات قصيرة ثم قائمة بأهم 5 أرقام وماذا تعني للقرار.'};
const p='أنت محلل مالي ومحاسب خبير يتحدث العربية بوضوح.\n<النشاط>'+v.b+'</النشاط>\n<المهمة>'+T[v.t]+'</المهمة>\n<البيانات>\n'+(v.d||'[ألصق هنا]')+'\n</البيانات>\nالقواعد: لا تخترع أرقامًا غير موجودة. إن نقصت معلومة اسأل أولًا. اعرض الحساب بخطوات يمكنني التحقق منها. نبّه عند الحاجة لمراجعة محاسب قانوني.';return aiOut(p)}''', ai=True)

