add('marketing-budget', 'marketing', '💸', 'موزّع ميزانية التسويق', 'وزّع ميزانيتك على القنوات بحسب هدفك.',
 [F('b', 'الميزانية الشهرية', 'n', 5000), S('g', 'الهدف', [('sales', 'مبيعات مباشرة'), ('aware', 'وعي بالعلامة'), ('leads', 'عملاء محتملون')])],
 r'''function compute(v){const P={sales:[['إعلانات بحث/تسوق',35],['إعلانات اجتماعية',30],['إعادة استهداف',15],['محتوى وتعاون مؤثرين',10],['بريد وواتساب',5],['أدوات وتحليل',5]],aware:[['فيديو قصير/اجتماعي',35],['مؤثرون',25],['محتوى وسيو',20],['إعلانات عرض',10],['فعاليات/شراكات',5],['أدوات',5]],leads:[['إعلانات اجتماعية بنماذج',35],['بحث',25],['محتوى ومقالات',15],['بريد وأتمتة',10],['شراكات',10],['أدوات',5]]}[v.g];
return tbl(['القناة','النسبة','المبلغ'],P.map(r=>[r[0],r[1]+'%',f(v.b*r[1]/100,0)]))+note('نسب استرشادية. أعد التوزيع بعد 4 أسابيع حسب النتائج الفعلية (CPA/ROAS).')}''')

add('content-calendar', 'marketing', '🗓️', 'مولّد تقويم المحتوى (30 يومًا)', 'تقويم محتوى جاهز من مواضيعك.',
 [F('tp', 'مواضيعك (سطر لكل موضوع)', 'textarea', 'نصائح استخدام المنتج\nقصة العلامة\nأسئلة العملاء\nعرض الأسبوع', r=5), F('pw', 'منشورات أسبوعيًا', 'n', 5), F('pl', 'المنصات (فاصلة)', 't', 'انستغرام, تيك توك, إكس')],
 r'''function compute(v){const T=lines(v.tp).map(r=>r[0]),P=v.pl.split(/[,،]/).map(s=>s.trim()).filter(Boolean),K=['فيديو قصير','صورة/كاروسيل','قصة تفاعلية','نص قصير','بث مباشر','شهادة عميل','سؤال وجواب'];if(!T.length||!P.length)return'أضف مواضيع ومنصات';const per=Math.max(1,Math.min(7,Math.round(v.pw)));const rows=[];let k=0;for(let d=1;d<=30;d++){if(((d-1)%7)<per){rows.push([d,P[k%P.length],K[k%K.length],esc(T[k%T.length])]);k++}}
return tbl(['اليوم','المنصة','النوع','الموضوع'],rows)+note('جدول أولي. عدّل الأفكار ووقت النشر حسب جمهورك.')}''')

add('ad-copy-generator', 'marketing', '✍️', 'مولّد نصوص إعلانية', 'ثلاث صيغ إعلان من منتجك وفائدته.',
 [F('pr', 'المنتج', 't', 'قهوة مختصة'), F('bn', 'الفائدة الأهم', 't', 'نكهة غنية بدون مرارة'), F('au', 'الجمهور', 't', 'محبو القهوة'), F('of', 'العرض', 't', 'شحن مجاني اليوم'), S('fm', 'الصيغة', [('aida', 'AIDA'), ('pas', 'PAS'), ('bab', 'قبل/بعد/جسر')])],
 r'''function compute(v){const A={aida:['انتباه: '+v.au+'، هل جرّبتم '+v.pr+'؟','اهتمام: '+v.bn+'.','رغبة: تخيّل الفرق من أول استخدام.','إجراء: '+v.of+' — اطلب الآن.'],pas:['مشكلة: تبحث عن '+v.pr+' ولا تجد ما يناسبك؟','تعميق: الاختيار الخاطئ يضيّع وقتك ومالك.','حل: '+v.pr+' — '+v.bn+'.','إجراء: '+v.of+'.'],bab:['قبل: يوم عادي بدون '+v.pr+'.','بعد: '+v.bn+'.','جسر: ابدأ اليوم مع '+v.pr+' — '+v.of+'.']}[v.fm];
const hl=[v.pr+': '+v.bn,v.of+' | '+v.pr,'لـ'+v.au+': '+v.pr];
return '<h3>عناوين مقترحة</h3><ul>'+hl.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><h3>النص</h3><pre class="tpl" id="pr">'+esc(A.join('\n'))+'</pre>'+note('نصوص أولية: خصّصها بنبرتك وتجنب الوعود غير المؤكدة.')}''')

add('utm-builder', 'marketing', '🔗', 'منشئ روابط التتبع UTM', 'ابنِ رابطًا يتتبع مصدر كل زيارة ومبيعة.',
 [F('u', 'رابط الصفحة', 't', 'https://example.com/product'), F('s', 'المصدر source', 't', 'instagram'), F('m', 'الوسيط medium', 't', 'social'), F('c', 'الحملة campaign', 't', 'white_friday'), F('t', 'الكلمة term (اختياري)', 't', ''), F('x', 'المحتوى content (اختياري)', 't', 'video1')],
 r'''function compute(v){let u=v.u.trim();if(!u)return'أدخل الرابط';const q=[['utm_source',v.s],['utm_medium',v.m],['utm_campaign',v.c],['utm_term',v.t],['utm_content',v.x]].filter(a=>a[1]).map(a=>a[0]+'='+encodeURIComponent(a[1].trim().toLowerCase().replace(/\s+/g,'_'))).join('&');const o=u+(u.includes('?')?'&':'?')+q;
return '<pre class="tpl" id="pr" dir="ltr" style="text-align:left">'+esc(o)+'</pre>'+note('استخدم أسماء موحدة (أحرف صغيرة بلا مسافات) لتجمع التقارير بشكل صحيح.')}''')

add('seo-meta-checker', 'marketing', '🔎', 'فاحص العنوان والوصف للسيو', 'عدّاد أحرف ومعاينة تقريبية لنتيجة جوجل.',
 [F('t', 'عنوان الصفحة', 't', 'حاسبة الهامش وسعر البيع للمتاجر | DIAMOND TV'), F('d', 'وصف الصفحة', 'textarea', 'احسب سعر البيع المناسب لمتجرك بعد الشحن والعمولات والإعلان والضريبة، مجانًا.', r=3), F('k', 'الكلمة المفتاحية', 't', 'حاسبة الهامش')],
 r'''function compute(v){const tl=v.t.length,dl=v.d.length;const ok=(x,a,b)=>x>=a&&x<=b?'good':'bad';const kw=v.k.trim();const inT=kw&&v.t.includes(kw),inD=kw&&v.d.includes(kw);
return kpis([kpi('طول العنوان',tl+' (الأفضل 30-60)',ok(tl,30,60)),kpi('طول الوصف',dl+' (الأفضل 90-160)',ok(dl,90,160)),kpi('الكلمة في العنوان',inT?'نعم':'لا',inT?'good':'bad'),kpi('الكلمة في الوصف',inD?'نعم':'لا',inD?'good':'bad')])+'<div style="background:#fff;border:1px solid #e6e0f5;border-radius:12px;padding:14px"><div style="color:#1a0dab;font-size:19px">'+esc(v.t.slice(0,62))+'</div><div style="color:#006621;font-size:14px">example.com › page</div><div style="color:#545454">'+esc(v.d.slice(0,160))+'</div></div>'+note('الحدود تقريبية: جوجل يعدّل العرض بحسب الجهاز.')}''')

add('persona-builder', 'marketing', '🧑‍🤝‍🧑', 'مجهّز شخصية العميل (Persona)', 'جهّز برومت يبني شخصية عميل مثالي مفصلة.',
 [F('p', 'المنتج/الخدمة', 't', 'عطور عربية'), F('m', 'السوق', 't', 'السعودية'), F('a', 'ما تعرفه عن عملائك', 'textarea', 'أغلبهم نساء 25-40، يشترون للهدايا، يهتمون بالتغليف', r=4)],
 r'''function compute(v){return aiOut('أنت خبير أبحاث تسويق. ابنِ 3 شخصيات (Personas) لعملاء '+v.p+' في '+v.m+'.\nالمعطيات: '+v.a+'\nلكل شخصية: الاسم والعمر والمهنة، الدوافع، الاعتراضات، أين تقضي وقتها على الإنترنت، الرسالة التسويقية الأنسب، وأفضل عرض. اختم بجدول يقارن الشخصيات. لا تخترع إحصاءات؛ وضّح أنها افتراضات تحتاج اختبارًا.')}''', ai=True)

add('marketing-ai-prompts', 'marketing', '🤖', 'مجهّز برومت التسويق بالذكاء الاصطناعي', 'جهّز طلبًا لحملات ومحتوى وتحليل منافسين.',
 [S('t', 'المهمة', [('cm', 'خطة حملة 30 يومًا'), ('cp', 'تحليل منافسين'), ('em', 'سلسلة بريد ترحيبية'), ('hk', '20 عنوانًا وخطافًا'), ('rp', 'تقرير أداء من أرقام')]), F('b', 'النشاط/المنتج', 't', 'متجر ملابس أطفال'), F('g', 'الهدف', 't', 'رفع المبيعات 20%'), F('x', 'ملاحظات وأرقام', 'textarea', '', r=4)],
 r'''function compute(v){const T={cm:'ضع خطة حملة 30 يومًا: أسبوعًا بأسبوع، القنوات، نوع المحتوى، الميزانية الموزعة، المؤشرات، وما أقيسه كل أسبوع.',cp:'حلّل 3 منافسين (أطلب منك أن تسألني عن أسمائهم): نقاط قوتهم، عروضهم، ثغراتهم، وكيف أتميز.',em:'اكتب سلسلة من 5 رسائل بريد ترحيبية: العنوان والمحتوى ودعوة الإجراء لكل رسالة وتوقيت الإرسال.',hk:'اكتب 20 عنوانًا وخطافًا بصيغ مختلفة (سؤال، رقم، مشكلة، فضول…) ورتب أفضل 5.',rp:'حلّل أرقام الحملة التالية: ما الذي نجح وما الذي فشل، وما 3 قرارات أتخذها الأسبوع القادم.'};
return aiOut('أنت استراتيجي تسويق رقمي يتحدث العربية.\n<النشاط>'+v.b+'</النشاط>\n<الهدف>'+v.g+'</الهدف>\n<المهمة>'+T[v.t]+'</المهمة>\n<ملاحظات>'+(v.x||'لا يوجد')+'</ملاحظات>\nلا تخترع أرقامًا. اسألني عن أي نقص قبل أن تبدأ.')}''', ai=True)

# ============ ECOM INNOVATIONS ============
add('reverse-profit-planner', 'ecom', '🎯', 'مخطط الأرباح العكسي', 'حدّد ربحك الشهري المستهدف فيحسب لك الطلبات والزيارات والإعلان المطلوبة.',
 [F('tg', 'صافي الربح المستهدف شهريًا', 'n', 10000), F('pr', 'سعر البيع', 'n', 120), F('vc', 'تكلفة المنتج + الشحن + العمولات للوحدة', 'n', 65), F('ad', 'تكلفة الزيارة (CPC)', 'n', 0.8), F('cv', 'معدل التحويل %', 'n', 2), F('fx', 'مصروفات ثابتة شهرية', 'n', 3000)],
 r'''function compute(v){const m=v.pr-v.vc;if(m<=0)return'سعر البيع لا يغطي التكلفة.';const cpa=v.cv?v.ad/(v.cv/100):0;const m2=m-cpa;if(m2<=0)return'تكلفة الإعلان لكل بيعة ('+f(cpa)+') تأكل كل هامشك ('+f(m)+'). ارفع التحويل أو السعر أو اخفض CPC.';const orders=Math.ceil((v.tg+v.fx)/m2);const vis=Math.ceil(orders/(v.cv/100));
return kpis([kpi('الطلبات المطلوبة',f(orders,0),'good'),kpi('الزيارات المطلوبة',f(vis,0)),kpi('ميزانية الإعلان',f(vis*v.ad,0),'bad'),kpi('CPA لكل بيعة',f(cpa)),kpi('ربح الوحدة بعد الإعلان',f(m2))])+note('إن بدا الرقم مستحيلًا فهذه فائدة الأداة: غيّر السعر أو التحويل أو الهدف قبل أن تنفق.')}''')

add('scenario-simulator', 'ecom', '🧪', 'محاكي سيناريوهات الربح', 'قارن ثلاثة سيناريوهات (حاليّ/متفائل/متحفظ) للسعر والإعلان والمرتجعات.',
 [F('un', 'الطلبات الشهرية الحالية', 'n', 200), F('pr', 'السعر الحالي', 'n', 100), F('vc', 'تكلفة الوحدة الكاملة (بلا إعلان)', 'n', 55), F('ad', 'تكلفة الإعلان للطلب', 'n', 15), F('rt', 'نسبة المرتجعات %', 'n', 6), F('fx', 'مصروفات ثابتة', 'n', 4000), F('pc', 'تغيّر السعر في السيناريو %', 'n', 10), F('vl', 'تغيّر الطلبات عند تغيير السعر %', 'n', -8)],
 r'''function compute(v){const sc=(n,p,a,r)=>{const rev=n*p*(1-r/100);const cost=n*(v.vc+a)+v.fx;return rev-cost};
const base=sc(v.un,v.pr,v.ad,v.rt);const up=sc(v.un*(1+v.vl/100),v.pr*(1+v.pc/100),v.ad,v.rt);const ads=sc(v.un*1.15,v.pr,v.ad*1.25,v.rt);const ret=sc(v.un,v.pr,v.ad,v.rt/2);
const rows=[['الوضع الحالي',f(base),'-'],['رفع السعر '+f(v.pc,0)+'% (الطلبات '+f(v.vl,0)+'%)',f(up),f(up-base)],['زيادة الإعلان (طلبات +15%، تكلفة +25%)',f(ads),f(ads-base)],['خفض المرتجعات للنصف',f(ret),f(ret-base)]];
const best=Math.max(up,ads,ret);return tbl(['السيناريو','صافي الربح الشهري','الفرق'],rows)+note('الأفضل هنا: '+(best===up?'تعديل السعر':best===ads?'زيادة الإعلان':'خفض المرتجعات')+'. هذه محاكاة بافتراضاتك، فاختبر الواقع بحملات صغيرة.')}''')

add('ab-test-significance', 'ecom', '🧬', 'حاسبة دلالة اختبار A/B', 'هل الفرق بين النسختين حقيقي أم صدفة؟',
 [F('va', 'زيارات النسخة A', 'n', 2000), F('ca', 'مبيعات A', 'n', 40), F('vb', 'زيارات النسخة B', 'n', 2000), F('cb', 'مبيعات B', 'n', 58)],
 r'''function compute(v){const pa=v.ca/v.va,pb=v.cb/v.vb;const p=(v.ca+v.cb)/(v.va+v.vb);const se=Math.sqrt(p*(1-p)*(1/v.va+1/v.vb));const z=se?(pb-pa)/se:0;const erf=x=>{const s=x<0?-1:1;x=Math.abs(x);const t=1/(1+0.3275911*x);const y=1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-0.284496736)*t+0.254829592)*t*Math.exp(-x*x);return s*y};const cdf=x=>0.5*(1+erf(x/Math.SQRT2));const pv=2*(1-cdf(Math.abs(z)));const conf=(1-pv)*100;const lift=pa?(pb-pa)/pa*100:0;
return kpis([kpi('تحويل A',f(pa*100)+'%'),kpi('تحويل B',f(pb*100)+'%'),kpi('الفرق النسبي',f(lift,1)+'%',lift>0?'good':'bad'),kpi('الثقة الإحصائية',f(conf,1)+'%',conf>=95?'good':'bad')])+'<p>'+(conf>=95?'✅ الفرق غالبًا حقيقي (ثقة ≥ 95%).':conf>=80?'🟡 مؤشر أولي: واصل الاختبار لعينة أكبر.':'🔴 الفرق قد يكون صدفة: لا تقرر بعد.')+'</p>'+note('اختبار z لنسبتين تقريبي. لا توقف الاختبار مبكرًا بمجرد ظهور فرق؛ حدّد حجم العينة مسبقًا.')}''')

add('ltv-cac', 'ecom', '♻️', 'حاسبة قيمة العميل LTV وتكلفة اكتسابه CAC', 'هل يستحق اكتساب العميل ما تدفعه؟',
 [F('aov', 'متوسط قيمة الطلب', 'n', 150), F('mg', 'هامش الربح الإجمالي %', 'n', 40), F('fr', 'عدد مرات الشراء في السنة', 'n', 2.5), F('lf', 'عمر العميل (سنوات)', 'n', 2), F('cac', 'تكلفة اكتساب العميل', 'n', 60)],
 r'''function compute(v){const ltv=v.aov*v.mg/100*v.fr*v.lf;const r=v.cac?ltv/v.cac:0;const pay=(v.aov*v.mg/100)?v.cac/(v.aov*v.mg/100):0;
return kpis([kpi('LTV (بالربح)',f(ltv),'good'),kpi('CAC',f(v.cac)),kpi('LTV ÷ CAC',f(r),r>=3?'good':'bad'),kpi('طلبات لاسترداد CAC',f(pay,1))])+'<p>'+(r>=3?'✅ نسبة صحية (3 فأكثر).':r>=1?'🟡 تربح لكن بهامش ضيق: ارفع التكرار أو اخفض CAC.':'🔴 تخسر على كل عميل جديد.')+'</p>'+note('القاعدة الشائعة: LTV/CAC ≥ 3. تعتمد على دقة افتراضاتك.')}''')

add('free-shipping-threshold', 'ecom', '🚚', 'حد الشحن المجاني الأمثل', 'اختر حدًا للشحن المجاني يرفع قيمة الطلب دون أن تخسر.',
 [F('aov', 'متوسط الطلب الحالي', 'n', 120), F('sh', 'تكلفة الشحن عليك', 'n', 20), F('mg', 'هامش الربح الإجمالي %', 'n', 40), F('up', 'نسبة العملاء الذين سيكملون للحد %', 'n', 30)],
 r'''function compute(v){const th=Math.ceil((v.aov*1.25)/10)*10;const gain=(th-v.aov)*v.mg/100*(v.up/100);const loss=v.sh*(1-v.up/100)*0.3;
return kpis([kpi('حد مقترح',f(th,0),'good'),kpi('زيادة ربح متوقعة/طلب',f(gain)),kpi('كلفة شحن إضافية متوقعة',f(loss),'bad')])+'<p>الفكرة: ضع حدًا أعلى من متوسطك بنحو 25% وأظهر شريط تقدم «باقي X للشحن المجاني». ربح الوحدة الإضافي يغطي الشحن إذا كان هامشك كافيًا.</p>'+note('اختبر الحد بـA/B لأسبوعين وراقب متوسط الطلب والتحويل معًا.')}''')

add('bundle-pricing', 'ecom', '🎁', 'مسعّر الباقات', 'اجمع منتجات في باقة بخصم يرفع الربح لا يخفضه.',
 [F('it', 'المنتجات (اسم | السعر | التكلفة)', 'textarea', 'منتج أ | 100 | 50\nمنتج ب | 60 | 25\nمنتج ج | 40 | 15', r=4), F('ds', 'خصم الباقة %', 'n', 12), F('ad', 'تكلفة إعلان/طلب', 'n', 12)],
 r'''function compute(v){const L=lines(v.it).map(r=>[r[0],num(r[1]),num(r[2])]);const sp=L.reduce((a,r)=>a+r[1],0),sc=L.reduce((a,r)=>a+r[2],0);const bp=sp*(1-v.ds/100);const bprof=bp-sc-v.ad;const sprof=sp-sc-v.ad*L.length;
return kpis([kpi('سعر الباقة',f(bp),'good'),kpi('ربح الباقة',f(bprof),bprof<0?'bad':'good'),kpi('ربح البيع المنفصل',f(sprof)),kpi('هامش الباقة',bp?f(bprof/bp*100,1)+'%':'-')])+note('الباقة تربح عندما يوفّر الإعلان الواحد عدة منتجات. تأكد أن خصمك لا يتجاوز ما توفره من الإعلان والشحن.')}''')

add('product-page-score', 'ecom', '📋', 'مقيّم جودة صفحة المنتج', 'فحص من 12 نقطة لصفحة منتجك مع نصائح.',
 [dict(id='c', l='ضع علامة (1) أمام كل ما هو موجود، سطر لكل نقطة', t='textarea', v='صور عالية الجودة من عدة زوايا|1\nفيديو قصير|0\nعنوان فيه كلمة البحث|1\nفوائد قبل المواصفات|1\nمواصفات ومقاسات واضحة|1\nتقييمات حقيقية|0\nصور العملاء|0\nسعر واضح بلا مفاجآت|1\nتكلفة الشحن ومدته ظاهرة|0\nسياسة إرجاع|1\nزر شراء واضح على الجوال|1\nأسئلة شائعة بالصفحة|0', r=12)],
 r'''function compute(v){const L=lines(v.c);const got=L.filter(r=>num(r[1])>0).length;const miss=L.filter(r=>!(num(r[1])>0)).map(r=>r[0]);const p=L.length?Math.round(got/L.length*100):0;
return kpis([kpi('درجة الصفحة',p+'%',p>=75?'good':'bad'),kpi('المتوفر',got+'/'+L.length)])+(miss.length?'<h3>ما ينقص صفحتك (أولوية للإصلاح)</h3><ul>'+miss.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>✅ صفحة مكتملة.</p>')+note('كل نقطة ناقصة تضعف الثقة أو التحويل. ابدأ بالتقييمات والشحن والصور.')}''')

add('launch-planner-30', 'ecom', '🚀', 'مخطط إطلاق منتج (30 يومًا)', 'أدخل تاريخ الإطلاق واحصل على جدول عد تنازلي.',
 [F('d', 'تاريخ الإطلاق', 'date', ''), F('p', 'اسم المنتج', 't', 'منتجي الجديد')],
 r'''function compute(v){const d=v.d?new Date(v.d):new Date(Date.now()+30*864e5);const S=[[-30,'اختبر الفكرة: استبيان أو إعلان تجريبي صغير'],[-25,'اطلب عينة نهائية وصوّر المنتج'],[-21,'جهّز صفحة المنتج والسياسات'],[-18,'جهّز نصوص الإعلانات (3 إبداعات)'],[-14,'افتح قائمة انتظار (واتساب/بريد)'],[-10,'ابدأ محتوى تشويقي يوميًا'],[-7,'تواصل مع صغار المؤثرين'],[-3,'اختبر الدفع والشحن بطلب تجريبي'],[-1,'جهّز ردود العملاء وقوالب الرسائل'],[0,'🚀 يوم الإطلاق: أرسل للقائمة وابدأ الإعلانات'],[3,'اطلب تقييمات من أول العملاء'],[7,'راجع الأرقام: CPA/ROAS/المرتجعات'],[14,'حسّن الصفحة بناءً على الأسئلة'],[30,'قيّم: هل تُكرّر الطلب أم تعدّل المنتج؟']];
return tbl(['التاريخ','المهمة'],S.map(s=>{const x=new Date(d.getTime()+s[0]*864e5);return[x.toLocaleDateString('ar-SA'),esc(s[1])]}))+note('مخطط عام للمنتج «'+esc(v.p)+'». عدّله بحسب مدة التوريد.')}''')

add('whatsapp-campaign', 'ecom', '💬', 'مولّد رسائل واتساب التسويقية', 'رسائل قصيرة بنبرة محترمة للعروض والتذكير وإعادة الشراء.',
 [F('st', 'اسم المتجر', 't', 'متجري'), F('nm', 'اسم العميل', 't', 'أحمد'), F('pr', 'المنتج', 't', 'القهوة المختصة'), F('of', 'العرض', 't', 'خصم 15% لمدة 48 ساعة'), F('lk', 'الرابط', 't', 'https://example.com')],
 r'''function compute(v){const M=[['عرض جديد','مرحبًا '+v.nm+' 👋\nمن '+v.st+': '+v.of+' على '+v.pr+'.\nللطلب: '+v.lk],['تذكير بإعادة الشراء','أهلًا '+v.nm+'،\nمرّ وقت منذ طلبك الأخير من '+v.pr+'. هل نجهّز لك طلبًا جديدًا؟ '+v.lk],['طلب تقييم','شكرًا لثقتك '+v.nm+'! رأيك في '+v.pr+' يساعدنا ويساعد غيرك: '+v.lk],['سلة متروكة','مرحبًا '+v.nm+'، تركت '+v.pr+' في السلة. إن كان عندك سؤال نحن هنا. أكمل طلبك: '+v.lk]];
return M.map(m=>'<h3>'+m[0]+'</h3><pre class="tpl">'+esc(m[1])+'</pre>').join('')+note('أرسل فقط لمن وافق على استقبال رسائلك، وأعطِ خيار إيقاف الرسائل.')}''')

add('occasions-planner', 'ecom', '📅', 'مخطط المواسم والعروض', 'مواسم البيع الرئيسية وتوقيت التحضير لها.',
 [S('m', 'الشهر', [(str(i), n) for i, n in enumerate(['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'], 1)], v='11')],
 r'''function compute(v){const O={1:['عودة الدراسة الفصل الثاني','عروض بداية العام'],2:['يوم التأسيس (22 فبراير)','تحضير رمضان'],3:['موسم رمضان والعيد (يتغير تاريخه سنويًا)','هدايا ومستلزمات'],4:['العيد وما بعده','عروض التصفية'],5:['موسم الاختبارات','تجهيز الصيف'],6:['بداية الصيف والسفر','عروض الإجازة'],7:['عروض الصيف','تجهيز العودة للمدارس'],8:['العودة للمدارس','القرطاسية والتقنية'],9:['اليوم الوطني (23 سبتمبر)','عروض وطنية'],10:['تجهيز الجمعة البيضاء','حجز الإعلانات مبكرًا'],11:['الجمعة البيضاء','عروض نهاية الشهر'],12:['الشتاء والهدايا','تصفية نهاية السنة']};
return '<ul>'+O[v.m].map(x=>'<li>'+x+'</li>').join('')+'</ul>'+note('تواريخ رمضان والأعياد تتغير سنويًا (هجري). تحقق من التقويم الرسمي. جهّز لأي موسم قبله بـ3 أسابيع.')}''')

# ============ MANAGEMENT ============
add('okr-builder', 'management', '🎯', 'مصمم الأهداف OKR وتتبع التقدم', 'هدف + نتائج رئيسية مع نسبة الإنجاز.',
 [F('o', 'الهدف (Objective)', 't', 'أن نصبح الخيار الأول لعملائنا في الخدمة'), F('k', 'النتائج الرئيسية (نتيجة | المستهدف | الحالي)', 'textarea', 'رفع رضا العملاء | 90 | 78\nخفض زمن الرد بالدقائق | 10 | 18\nزيادة التقييمات الإيجابية | 200 | 120', r=5)],
 r'''function compute(v){const rows=lines(v.k).map(r=>{const t=num(r[1]),c=num(r[2]);const p=t?Math.min(100,c/t*100):0;return[esc(r[0]||''),f(t,0),f(c,0),'<div class="meter"><i style="width:'+p+'%"></i></div> '+f(p,0)+'%',p]});const avg=rows.length?rows.reduce((a,r)=>a+r[4],0)/rows.length:0;
return '<h3>'+esc(v.o)+'</h3>'+kpis([kpi('إنجاز الهدف',f(avg,0)+'%',avg>=70?'good':'bad')])+tbl(['النتيجة','المستهدف','الحالي','التقدم'],rows.map(r=>r.slice(0,4)))+note('لنتيجة رئيسية قابلة للقياس: رقم + موعد. تجنّب الأنشطة (مثل «عقد اجتماعات») كنتائج.')}''')

add('swot-builder', 'management', '🧩', 'مصفوفة SWOT مع استراتيجيات', 'نقاط القوة والضعف والفرص والتهديدات في لوحة قابلة للطباعة.',
 [F('s', 'نقاط القوة', 'textarea', 'جودة منتجات\nخدمة سريعة', r=3), F('w', 'نقاط الضعف', 'textarea', 'ميزانية إعلان محدودة', r=3), F('o', 'الفرص', 'textarea', 'نمو التسوق الإلكتروني', r=3), F('t', 'التهديدات', 'textarea', 'منافسة أسعار', r=3)],
 r'''function compute(v){const li=t=>'<ul>'+lines(t).map(r=>'<li>'+esc(r[0])+'</li>').join('')+'</ul>';const bx=(c,h,t)=>'<div class="card" style="border-top:5px solid '+c+'"><h3>'+h+'</h3>'+li(t)+'</div>';
return '<div class="grid g2">'+bx('#0f9f6e','القوة',v.s)+bx('#c2410c','الضعف',v.w)+bx('#2563eb','الفرص',v.o)+bx('#7c3aed','التهديدات',v.t)+'</div><h3>استراتيجيات مقترحة (أكمل بنفسك)</h3><ul><li><b>SO:</b> كيف نستخدم القوة لاستغلال الفرص؟</li><li><b>WO:</b> كيف نعالج الضعف لنستفيد من الفرص؟</li><li><b>ST:</b> كيف نستخدم القوة لمواجهة التهديدات؟</li><li><b>WT:</b> كيف نتجنب الضعف والتهديد معًا؟</li></ul>'}''')

add('eisenhower-matrix', 'management', '🧱', 'مصفوفة الأولويات (أيزنهاور)', 'رتّب مهامك بين العاجل والمهم.',
 [F('t', 'المهام (مهمة | عاجل؟ ن/ل | مهم؟ ن/ل)', 'textarea', 'الرد على شكوى عميل | ن | ن\nتخطيط الشهر القادم | ل | ن\nرسالة روتينية | ن | ل\nتصفح عشوائي | ل | ل', r=6)],
 r'''function compute(v){const Q={'نن':[],'لن':[],'نل':[],'لل':[]};lines(v.t).forEach(r=>{const u=(r[1]||'').trim().startsWith('ن')?'ن':'ل',i=(r[2]||'').trim().startsWith('ن')?'ن':'ل';Q[u+i].push(esc(r[0]))});const bx=(h,a,c)=>'<div class="card" style="border-top:5px solid '+c+'"><h3>'+h+'</h3><ul>'+a.map(x=>'<li>'+x+'</li>').join('')+'</ul></div>';
return '<div class="grid g2">'+bx('1) افعلها الآن (عاجل ومهم)',Q['نن'],'#c2410c')+bx('2) جدولها (مهم غير عاجل)',Q['لن'],'#0f9f6e')+bx('3) فوّضها (عاجل غير مهم)',Q['نل'],'#2563eb')+bx('4) احذفها (لا عاجل ولا مهم)',Q['لل'],'#6b6391')+'</div>'}''')

add('meeting-minutes', 'management', '📝', 'مولّد جدول أعمال ومحضر اجتماع', 'جدول أعمال ثم محضر بقرارات ومهام.',
 [F('ti', 'عنوان الاجتماع', 't', 'مراجعة الأداء الأسبوعي'), F('dt', 'التاريخ', 'date', ''), F('at', 'الحضور (فاصلة)', 't', 'أحمد, سارة, خالد'), F('ag', 'بنود الجدول (سطر لكل بند | دقائق)', 'textarea', 'مراجعة الأرقام | 15\nمشكلات التشغيل | 20\nخطة الأسبوع | 15', r=4), F('dc', 'القرارات والمهام (مهمة | مسؤول | موعد)', 'textarea', 'تحديث صفحة المنتج | سارة | الخميس', r=3)],
 r'''function compute(v){const ag=lines(v.ag);const tot=ag.reduce((a,r)=>a+num(r[1]||0),0);
return '<div style="background:#fff;border:1px solid #e6e0f5;border-radius:14px;padding:16px"><h3>'+esc(v.ti)+'</h3><p>'+esc(v.dt)+' — الحضور: '+esc(v.at)+'</p><h4>جدول الأعمال ('+tot+' دقيقة)</h4><ol>'+ag.map(r=>'<li>'+esc(r[0])+' — '+esc(r[1]||'')+' د</li>').join('')+'</ol><h4>القرارات والمهام</h4>'+tbl(['المهمة','المسؤول','الموعد'],lines(v.dc).map(r=>[esc(r[0]||''),esc(r[1]||''),esc(r[2]||'')]))+'</div>'+note('اجعل كل اجتماع بجدول ومدة محددة وينتهي بمهام لها مسؤول وموعد.')}''')

add('project-planner', 'management', '🗺️', 'مخطط مشروع بسيط بالتواريخ', 'مهام متتابعة بمدد لتعرف تاريخ التسليم.',
 [F('st', 'تاريخ البدء', 'date', ''), F('t', 'المهام (مهمة | عدد الأيام)', 'textarea', 'جمع المتطلبات | 3\nالتصميم | 5\nالتنفيذ | 10\nالمراجعة | 3\nالإطلاق | 1', r=6), F('bf', 'هامش أمان %', 'n', 15)],
 r'''function compute(v){let d=v.st?new Date(v.st):new Date();const rows=[];let tot=0;lines(v.t).forEach(r=>{const n=Math.max(1,Math.round(num(r[1]||1)));const s=new Date(d);d=new Date(d.getTime()+n*864e5);tot+=n;rows.push([esc(r[0]||''),n,s.toLocaleDateString('ar-SA'),new Date(d.getTime()-864e5).toLocaleDateString('ar-SA')])});const buf=Math.ceil(tot*v.bf/100);const end=new Date(d.getTime()+buf*864e5-864e5);
return kpis([kpi('إجمالي الأيام',tot),kpi('هامش الأمان',buf+' يوم'),kpi('تسليم متوقع',end.toLocaleDateString('ar-SA'),'good')])+tbl(['المهمة','أيام','من','إلى'],rows)+note('تخطيط تتابعي مبسط. للمشاريع الكبيرة استخدم أداة إدارة مشاريع وحدّد الاعتماديات.')}''')

add('decision-matrix', 'management', '⚖️', 'مصفوفة القرار الموزونة', 'قارن خيارات بمعايير موزونة لتصل لقرار مبني على أرقام.',
 [F('c', 'المعايير (معيار | وزن 1-5)', 'textarea', 'السعر | 5\nالجودة | 4\nالسرعة | 3', r=4), F('o', 'الخيارات (اسم | درجات المعايير بالترتيب مفصولة بفاصلة، 1-5)', 'textarea', 'خيار أ | 4,3,5\nخيار ب | 3,5,3\nخيار ج | 5,2,2', r=4)],
 r'''function compute(v){const W=lines(v.c).map(r=>num(r[1]||1)),sw=W.reduce((a,b)=>a+b,0)||1;const R=lines(v.o).map(r=>{const s=(r[1]||'').split(/[,،]/).map(num);const t=s.reduce((a,x,i)=>a+x*(W[i]||0),0)/sw;return[esc(r[0]),t]}).sort((a,b)=>b[1]-a[1]);
return tbl(['الخيار','النتيجة الموزونة (من 5)'],R.map((r,i)=>[(i==0?'🏆 ':'')+r[0],f(r[1])]))+note('الأرقام تساعد القرار ولا تحل محل الحكم والخبرة. غيّر الأوزان لترى حساسية النتيجة.')}''')

add('management-ai-prompts', 'management', '🤖', 'مجهّز برومت المدير بالذكاء الاصطناعي', 'جهّز طلبات للتخطيط والتفويض وحل الخلافات.',
 [S('t', 'المهمة', [('pl', 'خطة ربع سنوية'), ('dl', 'خطة تفويض مهام'), ('fb', 'محادثة تقييم صعبة'), ('pr', 'تحليل أسباب مشكلة (5 لماذا)'), ('ch', 'خطة إدارة تغيير')]), F('b', 'الفريق/النشاط', 't', 'فريق مبيعات من 5 أشخاص'), F('x', 'التفاصيل', 'textarea', '', r=5)],
 r'''function compute(v){const T={pl:'ضع خطة ربع سنوية: 3 أهداف OKR، مبادرات لكل هدف، مؤشرات، مخاطر، وجدول مراجعة شهري.',dl:'ابنِ خطة تفويض: ما المهام التي أفوّضها ولمن، مستوى الصلاحية، نقاط المتابعة، وكيف أتجنب التدخل الزائد.',fb:'ساعدني في الاستعداد لمحادثة تقييم صعبة: هيكل المحادثة، عبارات محترمة وواضحة، ردود على اعتراضات محتملة، وخطوات المتابعة.',pr:'حلّل المشكلة بطريقة «5 لماذا»، واقترح حلولًا قصيرة وطويلة المدى وكيف أتحقق من نجاحها.',ch:'ضع خطة إدارة تغيير: أصحاب المصلحة، رسائل التواصل، مقاومة متوقعة وكيف أعالجها، ومؤشرات التبني.'};
return aiOut('أنت مستشار إداري خبير يتحدث العربية بعملية.\n<السياق>'+v.b+'</السياق>\n<المهمة>'+T[v.t]+'</المهمة>\n<التفاصيل>'+(v.x||'اسألني عما ينقص')+'</التفاصيل>\nاجعل الإجابة قابلة للتنفيذ وبشكل منظم.')}''', ai=True)

