add('job-description', 'hr', '📄', 'مولّد الوصف الوظيفي', 'وصف وظيفي منظم جاهز للنشر.',
 [F('ti', 'المسمى الوظيفي', 't', 'مسؤول خدمة عملاء'), F('dp', 'القسم', 't', 'خدمة العملاء'), F('lv', 'المستوى', 't', 'مبتدئ - متوسط'), F('rs', 'المسؤوليات (سطر لكل مسؤولية)', 'textarea', 'الرد على استفسارات العملاء\nمعالجة الشكاوى\nتحديث سجلات الطلبات', r=4), F('rq', 'المتطلبات', 'textarea', 'خبرة سنة\nمهارات تواصل ممتازة\nإجادة الحاسب', r=4), F('bn', 'المزايا', 'textarea', 'راتب تنافسي\nتأمين طبي', r=3)],
 r'''function compute(v){const li=t=>lines(t).map(r=>'<li>'+esc(r[0])+'</li>').join('');
return '<div style="background:#fff;border:1px solid #e6e0f5;border-radius:14px;padding:16px"><h2>'+esc(v.ti)+'</h2><p>القسم: '+esc(v.dp)+' — المستوى: '+esc(v.lv)+'</p><h3>المسؤوليات</h3><ul>'+li(v.rs)+'</ul><h3>المتطلبات</h3><ul>'+li(v.rq)+'</ul><h3>ما نقدمه</h3><ul>'+li(v.bn)+'</ul></div>'+note('اذكر الراتب أو نطاقه إن أمكن فهذا يرفع جودة المتقدمين. تجنب العبارات التمييزية.')}''')

add('interview-kit', 'hr', '🎤', 'حقيبة المقابلة وبطاقة التقييم', 'أسئلة بحسب الكفاءة وبطاقة تقييم.',
 [F('r', 'الوظيفة', 't', 'مندوب مبيعات'), S('c', 'الكفاءة', [('com', 'التواصل'), ('pro', 'حل المشكلات'), ('tea', 'العمل الجماعي'), ('res', 'تحمل الضغط'), ('own', 'المسؤولية والمبادرة')])],
 r'''function compute(v){const Q={com:['حدّثني عن موقف شرحت فيه فكرة صعبة لشخص لا يعرف الموضوع.','كيف تتأكد أن رسالتك فُهمت؟'],pro:['صف مشكلة معقدة حللتها: ما خطواتك؟','متى كان قرارك خاطئًا وماذا تعلمت؟'],tea:['حدثني عن خلاف مع زميل وكيف عالجته.','ماذا تفعل إن لم يلتزم أحد أفراد الفريق؟'],res:['موقف عمل تحت ضغط شديد: كيف تصرفت؟','كيف ترتب أولوياتك عند تعدد المهام؟'],own:['مبادرة قمت بها دون أن يُطلب منك.','موقف تحملت فيه مسؤولية خطأ.']};
return '<h3>أسئلة ('+esc(v.r)+')</h3><ol>'+Q[v.c].map(x=>'<li>'+x+' <small>(اسأل: الموقف، دورك، الفعل، النتيجة)</small></li>').join('')+'</ol><h3>بطاقة التقييم</h3>'+tbl(['المعيار','1','2','3','4','5'],[['وضوح الإجابة','☐','☐','☐','☐','☐'],['أمثلة فعلية','☐','☐','☐','☐','☐'],['الملاءمة للوظيفة','☐','☐','☐','☐','☐'],['الدافعية','☐','☐','☐','☐','☐']])+note('اسأل جميع المرشحين الأسئلة نفسها وقيّمهم بالمعايير نفسها لتقليل التحيز.')}''')

add('end-of-service', 'hr', '🧳', 'حاسبة مكافأة نهاية الخدمة (تقديرية)', 'تقدير وفق قواعد نظام العمل السعودي المعروفة.',
 [F('w', 'آخر أجر شهري شامل (أساسي + بدلات ثابتة)', 'n', 8000), F('y', 'سنوات الخدمة', 'n', 6), F('m', 'أشهر إضافية', 'n', 0), S('c', 'سبب انتهاء العلاقة', [('end', 'انتهاء العقد / إنهاء من صاحب العمل'), ('res', 'استقالة العامل')])],
 r'''function compute(v){const yrs=v.y+v.m/12;const first=Math.min(yrs,5),rest=Math.max(0,yrs-5);let full=first*0.5*v.w+rest*v.w;let k=1,txt='كامل المكافأة';if(v.c==='res'){if(yrs<2){k=0;txt='لا تستحق عادة (أقل من سنتين)'}else if(yrs<5){k=1/3;txt='ثلث المكافأة'}else if(yrs<10){k=2/3;txt='ثلثا المكافأة'}}
return kpis([kpi('المكافأة التقديرية',f(full*k),'good'),kpi('قبل التخفيض',f(full)),kpi('الاستحقاق',txt)])+note('تقدير مبني على القواعد المعروفة: نصف أجر شهر عن كل سنة من أول 5 سنوات، وأجر شهر عن كل سنة بعدها، وتخفيض عند الاستقالة. النظام يتحدث ولكل حالة تفاصيل، فراجع نظام العمل الرسمي أو مختصًا قبل أي صرف.')}''')

add('salary-breakdown', 'hr', '💵', 'محلل الراتب والأوفرتايم', 'تفصيل الراتب وأجر الساعة وبدل العمل الإضافي.',
 [F('b', 'الراتب الأساسي', 'n', 6000), F('h', 'بدل السكن %', 'n', 25), F('t', 'بدل النقل', 'n', 500), F('o', 'بدلات أخرى', 'n', 0), F('hrs', 'ساعات الأسبوع', 'n', 48), F('ot', 'ساعات عمل إضافي هذا الشهر', 'n', 10)],
 r'''function compute(v){const hs=v.b*v.h/100,tot=v.b+hs+v.t+v.o;const hr=v.b/(v.hrs*52/12);const otp=hr*1.5*v.ot;
return kpis([kpi('الراتب الشامل',f(tot),'good'),kpi('بدل السكن',f(hs)),kpi('أجر الساعة (أساسي)',f(hr)),kpi('أجر الإضافي',f(otp)),kpi('الإجمالي مع الإضافي',f(tot+otp))])+note('الإضافي يُحسب غالبًا بأجر الساعة الأساسي + 50%. الخصومات (تأمينات) غير مشمولة. راجع النظام ومختصك.')}''')

add('leave-balance', 'hr', '🏖️', 'رصيد الإجازة السنوية', 'احسب المستحق والمتبقي من الإجازة.',
 [F('hd', 'تاريخ التعيين', 'date', '2022-03-01'), F('us', 'أيام استخدمتها هذه السنة', 'n', 8)],
 r'''function compute(v){const hd=v.hd?new Date(v.hd):new Date();const now=new Date();const yrs=(now-hd)/(365.25*864e5);const ent=yrs>=5?30:21;const ys=new Date(now.getFullYear(),0,1);const start=hd>ys?hd:ys;const frac=Math.max(0,(now-start)/(365.25*864e5));const acc=Math.min(ent,ent*frac);
return kpis([kpi('سنوات الخدمة',f(yrs,1)),kpi('الاستحقاق السنوي',ent+' يوم'),kpi('مستحق حتى اليوم',f(acc,1)),kpi('المتبقي',f(acc-v.us,1),acc-v.us<0?'bad':'good')])+note('القاعدة المعتادة: 21 يومًا سنويًا و30 بعد 5 سنوات. قد تمنح شركتك أكثر. راجع نظامها.')}''')

add('onboarding-checklist', 'hr', '🧑‍💼', 'قائمة تهيئة الموظف الجديد', 'قبل اليوم الأول وحتى اليوم 90.',
 [F('n', 'اسم الموظف', 't', ''), F('s', 'تاريخ المباشرة', 'date', '')],
 r'''function compute(v){const G=[['قبل المباشرة',['إرسال عقد/خطاب العرض','تجهيز جهاز وحسابات','تعريف الفريق بالموظف','تجهيز مكان العمل']],['اليوم الأول',['جولة وتعريف بالفريق','شرح الثقافة والسياسات','تعيين زميل مرشد','تحديد أهداف أول أسبوع']],['الشهر الأول',['تدريب على الأنظمة','لقاء أسبوعي مع المدير','تسليم مهمة صغيرة','جمع ملاحظات مبكرة']],['اليوم 90',['مراجعة الأداء والأهداف','تقييم التهيئة من الموظف','خطة تطوير']]];
return '<h3>تهيئة '+esc(v.n||'موظف جديد')+(v.s?' ('+esc(v.s)+')':'')+'</h3>'+G.map(g=>'<h4>'+g[0]+'</h4>'+g[1].map(x=>'<label class="chk"><input type="checkbox"><span>'+x+'</span></label>').join('')).join('')}''')

add('performance-review', 'hr', '⭐', 'نموذج تقييم الأداء', 'قيّم المعايير بأوزان واحصل على النتيجة النهائية.',
 [F('n', 'اسم الموظف', 't', ''), F('c', 'المعايير (معيار | وزن % | درجة 1-5)', 'textarea', 'جودة العمل | 30 | 4\nالإنتاجية | 25 | 3\nالتعاون | 20 | 5\nالمبادرة | 15 | 3\nالالتزام | 10 | 4', r=6)],
 r'''function compute(v){const R=lines(v.c);const tw=R.reduce((a,r)=>a+num(r[1]||0),0)||1;const sc=R.reduce((a,r)=>a+num(r[1]||0)*num(r[2]||0),0)/tw;const g=sc>=4.5?'متميز':sc>=3.5?'ممتاز/جيد جدًا':sc>=2.5?'مقبول':'يحتاج تحسينًا';
return kpis([kpi('النتيجة من 5',f(sc),sc>=3.5?'good':'bad'),kpi('التقدير',g),kpi('مجموع الأوزان',f(tw,0)+'%')])+tbl(['المعيار','الوزن','الدرجة'],R.map(r=>[esc(r[0]),esc(r[1]||''),esc(r[2]||'')]))+note('اكتب لكل درجة مثالًا سلوكيًا. وناقش النتيجة بحوار لا بإعلان.')}''')

add('hr-ai-prompts', 'hr', '🤖', 'مجهّز برومت الموارد البشرية بالذكاء الاصطناعي', 'جهّز طلبات للتوظيف والسياسات والتواصل.',
 [S('t', 'المهمة', [('jd', 'إعلان وظيفي جذاب'), ('sc', 'فرز سير ذاتية بمعايير'), ('po', 'سياسة (إجازات/دوام/سلوك)'), ('ex', 'رسالة رفض مرشح باحترام'), ('of', 'خطاب عرض وظيفي')]), F('b', 'الشركة والوظيفة', 't', 'متجر إلكتروني - مسؤول خدمة عملاء'), F('x', 'التفاصيل', 'textarea', '', r=5)],
 r'''function compute(v){const T={jd:'اكتب إعلانًا وظيفيًا جذابًا وواضحًا: نبذة، المسؤوليات، المتطلبات، المزايا، وطريقة التقديم، بنبرة محترمة وغير تمييزية.',sc:'أنشئ معايير فرز موضوعية من 5 نقاط مع أوزانها، ثم أعطني جدول تقييم أطبّقه على كل سيرة، دون الاعتماد على الاسم أو الجنس أو العمر.',po:'اكتب مسودة سياسة موارد بشرية واضحة وعادلة في صفحة واحدة، مع تنبيهي لما يجب مراجعته قانونيًا في بلدي.',ex:'اكتب رسالة رفض لمرشح بعد المقابلة: محترمة وقصيرة وتشجعه على التقديم لاحقًا دون وعود كاذبة.',of:'اكتب خطاب عرض وظيفي: المسمى، تاريخ البدء، الراتب والبدلات، فترة التجربة، شروط عامة، مع ملاحظة لمراجعة قانونية.'};
return aiOut('أنت أخصائي موارد بشرية يتحدث العربية.\n<السياق>'+v.b+'</السياق>\n<المهمة>'+T[v.t]+'</المهمة>\n<التفاصيل>'+(v.x||'اسألني عما ينقص')+'</التفاصيل>\nلا تتخذ قرارات توظيف عني؛ ساعدني في التنظيم والصياغة فقط، وتجنب أي تمييز.')}''', ai=True)
